-- Resources: Underwriting & Traffic tutorial guides
-- (docs/resources-design.md slice 5). Three gaps in the tool's guide set:
-- the five-step contract setup wizard, copy/rotation/placement, and the
-- exceptions/makegoods/affidavits workflow -- alongside the one guide
-- seeded with Resources itself (find-and-filter-contracts). Exceptions,
-- makegoods, and affidavits have no dedicated screen key in
-- lib/resources/screens.ts (same as this tool's own dashboard) -- Help
-- still lists this guide for the tool, just not scoped to one screen.
-- Content only. Upserts on slug; guarded by edited_since_release.

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'underwriting-set-up-a-contract', 'guide'::public.rc_kind, 'Setting up a contract', 'Walk a signed order through five steps, from the sponsor and total down to activation.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A contract''s setup is five steps end to end, taking a signed order from a blank form to something that can actually be scheduled."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Order"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select the underwriter, enter the order number, the sponsorship total, the campaign''s run dates, a sponsorship category, and an account rep, with optional notes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Continue to schedule","marks":[{"type":"bold"}]},{"type":"text","text":" — or, instead of typing everything by hand, upload the signed agreement under “Or start from the signed agreement” and select "},{"type":"text","text":"Create from the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" to have it read from the document. What you''ve already typed always wins over its reading."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"Add each line from the order — pool or program, days, dates, spot count, and the rest — through the schedule line editor, one at a time. Select "},{"type":"text","text":"Continue to copy","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Copy"}]},{"type":"paragraph","content":[{"type":"text","text":"Link or create the underwriting messages this contract will run, on the Copy step — the same panel the contract''s own Copy tab uses later. Select "},{"type":"text","text":"Continue to traffic policy","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Traffic policy"}]},{"type":"paragraph","content":[{"type":"text","text":"Set the total spots on the order, the preemption/makegood policy, whether an affidavit is required, whether makegoods need agency approval, and separation. Select "},{"type":"text","text":"Save policy","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Continue to review","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review and activate"}]},{"type":"paragraph","content":[{"type":"text","text":"The contract page shows a “Ready to activate?” checklist against the order, agreement, schedule, copy, and policy, each with a fix-it link if something''s missing. Select "},{"type":"text","text":"Activate contract","marks":[{"type":"bold"}]},{"type":"text","text":" once it''s clear."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing schedules until activation — a draft contract can be edited freely, and can be deleted outright if it turns out not to be needed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"“Create from the agreement” reads a scanned or photographed signed order with one model call; it never invents a sponsor, program, or pool that isn''t already on file — an unrecognized name is refused, not guessed."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{underwriting.contracts,underwriting.contract}'::text[], 20, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'underwriting'
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  tool_id = excluded.tool_id, screen_keys = excluded.screen_keys,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'underwriting-copy-and-placement', 'guide'::public.rc_kind, 'Copy, rotation, and placing a credit', 'Link a contract''s messages, then place a credit manually or let auto-fill do it.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A credit needs approved copy behind it before it can run anywhere."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Copy"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the contract''s Copy tab, select "},{"type":"text","text":"+ New message","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Link existing…","marks":[{"type":"bold"}]},{"type":"text","text":" to attach a script. A draft message can be approved right from its card — only approved copy rotates or gets placed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy shared across more than one contract shows which others use it, right on its edit card."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rotation"}]},{"type":"paragraph","content":[{"type":"text","text":"Rotation is automatic: each contract cycles through its own linked messages in broadcast order, with nothing for staff to pick. An aired, frozen, or manager-overridden placement is a fixed point that rotation won''t move."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Placing a credit"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Manually, from a schedule line''s "},{"type":"text","text":"Place a credit","marks":[{"type":"bold"}]},{"type":"text","text":" link: pick an open break (grouped by period), confirm or change the suggested message (already the next one in rotation), and select "},{"type":"text","text":"Place credit","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Or let auto-fill do it: "},{"type":"text","text":"Auto-fill this line","marks":[{"type":"bold"}]},{"type":"text","text":" from a line''s own menu, "},{"type":"text","text":"Auto-fill this contract","marks":[{"type":"bold"}]},{"type":"text","text":" for every line on one contract, or "},{"type":"text","text":"Auto-fill everything","marks":[{"type":"bold"}]},{"type":"text","text":" for every active contract — the same placement path either way, just run in a loop."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A same-underwriter or same-industry adjacency warning is advisory on the manual placement form — it''s shown, never blocked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-fill generates the rundowns it needs as it goes, so a fresh contract can be filled for its whole campaign in one click even before a rundown for those dates exists yet."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{underwriting.contract,underwriting.copy}'::text[], 30, 'editor'::public.rc_source, 'Initial version'
from public.tools t where t.key = 'underwriting'
