insert into public.rc_articles
  (slug, kind, title, summary, body, audience, tool_id, screen_keys, sort_order, source, version_note)
select
  'underwriting-exceptions-makegoods-affidavits', 'guide'::public.rc_kind, 'Exceptions, makegoods, and affidavits', 'Resolve a missed or preempted credit, then generate and certify an affidavit.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When a credit airs as anything other than scheduled, an exception is raised automatically — nobody has to go looking for it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Exceptions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The exceptions list filters to all, open, awaiting agency approval, or resolved."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On one, review what happened, record the agency''s answer if the contract requires approval, schedule a makegood if one''s owed, then set a resolution and select "},{"type":"text","text":"Save","marks":[{"type":"bold"}]},{"type":"text","text":". Waiving an exception needs a manager — anyone else''s attempt is refused."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Makegoods"}]},{"type":"paragraph","content":[{"type":"text","text":"A makegood awaiting a slot is normally picked up automatically the next time auto-fill runs. To schedule one by hand, pick an open break and a message (default: next in rotation) on the makegoods list, and select "},{"type":"text","text":"Schedule makegood","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Affidavits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Generate","marks":[{"type":"bold"}]},{"type":"text","text":", choose the contract and a period, and select "},{"type":"text","text":"Generate","marks":[{"type":"bold"}]},{"type":"text","text":" again to confirm. The affidavit page previews the document, with a "},{"type":"text","text":"Preview draft PDF","marks":[{"type":"bold"}]},{"type":"text","text":" button before certification."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Certifying is manager-only: fill in a title and select "},{"type":"text","text":"Certify and store PDF","marks":[{"type":"bold"}]},{"type":"text","text":". This freezes the affidavit as a signed PDF, with its checksum recorded — a correction afterward is always a new affidavit, never an edit to this one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An affidavit lists only aired credits, in Central time, with no dollar amounts — a rep sends it to the client directly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-generating for the same contract and period is fine; it produces a new, separately versioned affidavit rather than overwriting the previous one."}]}]}]}]}'::jsonb, '{staff,students,partners}'::public.rc_audience[],
  t.id, '{}'::text[], 40, 'editor'::public.rc_source, 'Initial version'
